using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
namespace Ara {
 public static class MealGapTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static State New(){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(15);GridEngine.Ensure(s,d);return s;}
  static void Record(Day d,string id,int minutes){d.Records.Add(new CellBlock{Id="actual-"+id,Start=d.Wake.AddMinutes(minutes),Count=3,MealId=id,Category="식사",Name=id,Score=2});}
  static void Gaps(GridPlan p){var meals=p.Blocks.Where(x=>!string.IsNullOrEmpty(x.MealId)).OrderBy(x=>x.Start).ToList();for(int i=1;i<meals.Count;i++)Assert(meals[i].Start>=meals[i-1].Start.AddHours(3),meals[i-1].MealId+"->"+meals[i].MealId);foreach(var prep in p.Blocks.Where(x=>!string.IsNullOrEmpty(x.PrepFor)))Assert(prep.End==p.Blocks.Single(x=>x.MealId==prep.PrepFor).Start,"prep follows meal");for(int i=1;i<p.Blocks.Count;i++)Assert(p.Blocks[i].Start>=p.Blocks[i-1].End,"nonoverlap");}
  public static void Run(Action<string,Action> check,string dir){
   check("meal gap: using yogurt preserves zone2 and three-hour meal gaps",()=>{var s=New();var d=s.Days[0];Record(d,"b1",270);var p=GridEngine.Build(s,d);Gaps(p);Assert(p.Blocks.Single(x=>x.MealId=="b6").Start==d.Records[0].Start.AddHours(3),"180-minute floor");Assert(p.Blocks.Any(x=>x.Category=="존2")&&p.Blocks.Single(x=>x.Category=="웨이트").Count==12,"zone and weights retained");});
   check("meal gap: first-meal delay sweep preserves every remaining meal and original baseline",()=>{for(int delay=0;delay<=800;delay+=10){var s=New();var d=s.Days[0];Record(d,"b1",30+delay);string baseline=PhoneCodec.Hash(PhoneCodec.Json(d.GridBase)),facts=PhoneCodec.Hash(PhoneCodec.Json(d.Records));var p=GridEngine.Build(s,d);Gaps(p);Assert(p.Blocks.Single(x=>x.Category=="웨이트").Start>=p.Blocks.Single(x=>x.MealId=="b6").Start.AddMinutes(150),"second-to-weight floor");Assert(PhoneCodec.Hash(PhoneCodec.Json(d.GridBase))==baseline&&PhoneCodec.Hash(PhoneCodec.Json(d.Records))==facts,"facts and baseline unchanged");Assert(Adaptive.Target(s,d)==d.Wake.AddMinutes(990),"fixed original bedtime");}});
   check("meal gap: actual eating duration does not change the start-to-start floor",()=>{var s=New();var d=s.Days[0];Record(d,"b1",270);d.Records[0].Count=6;var p=GridEngine.Build(s,d);Gaps(p);Assert(p.Blocks.Single(x=>x.MealId=="b6").Start==d.Records[0].Start.AddHours(3),"three hours from start, not end");Assert(GridEngine.Total(d)==12&&d.Records[0].Count==6,"duration and score preserved");});
   check("meal gap: actual meals closer than three hours remain facts with visible warning",()=>{var s=New();var d=s.Days[0];Record(d,"b1",30);Record(d,"b6",150);string facts=PhoneCodec.Hash(PhoneCodec.Json(d.Records));var p=GridEngine.Build(s,d);Assert(p.Blocks.Single(x=>x.MealId=="b1").Start==d.Records[0].Start&&p.Blocks.Single(x=>x.MealId=="b6").Start==d.Records[1].Start,"exact actual anchors");Assert(p.Changes.Any(x=>x.Contains("최소 180분 미달")&&x.Contains("실제 기록 보호")),"warning shown");Assert(PhoneCodec.Hash(PhoneCodec.Json(d.Records))==facts,"no fabricated time or score");});
   check("meal gap: short actual weights postpone fourth meal while preserving workout",()=>{var s=New();var d=s.Days[0];Record(d,"b10",450);d.Records.Add(new CellBlock{Id="weight",Start=d.Wake.AddMinutes(490),Count=3,Category="웨이트",TemplateId="b8",Score=3});var p=GridEngine.Build(s,d);Gaps(p);Assert(p.Blocks.Single(x=>x.MealId=="b15").Start>=d.Wake.AddMinutes(630),"fourth meal respects meal gap and fixed planned workout");Assert(p.Blocks.Single(x=>x.Category=="웨이트").Start==d.Wake.AddMinutes(490)&&d.Records.Last().Count==3,"workout facts protected");});
   check("meal gap: manually compacted future meals are postponed without mutating stored plan",()=>{var s=New();var d=s.Days[0];d.GridBase.RemoveAll(x=>x.Category=="존2"||x.Category=="웨이트"||x.Category=="생활");var second=d.GridBase.Single(x=>x.MealId=="b6");second.Start=d.Wake.AddMinutes(180);d.GridBase.Single(x=>x.PrepFor=="b6").Start=second.Start.AddMinutes(-10);string original=PhoneCodec.Hash(PhoneCodec.Json(d.GridBase));var p=GridEngine.Build(s,d);Gaps(p);Assert(p.Blocks.Single(x=>x.MealId=="b6").Start==d.Wake.AddMinutes(210),"180 minutes after first start");Assert(PhoneCodec.Hash(PhoneCodec.Json(d.GridBase))==original,"baseline restored on next build");});
   check("meal gap: phone snapshot uses the same constrained schedule as PC",()=>{var s=New();var d=s.Days[0];Record(d,"b1",270);var p=GridEngine.Build(s,d);var wire=PhoneCodec.Snapshot(s,d.Date);foreach(var block in p.DisplayBlocks)Assert(wire.planned.Single(x=>x.id==block.Id).start==(int)(block.Start-d.Wake.Date).TotalMinutes/10,"shared computed times");var meals=p.Blocks.Where(x=>!string.IsNullOrEmpty(x.MealId)).OrderBy(x=>x.Start).ToList();for(int i=1;i<meals.Count;i++)Assert(meals[i].Start>=meals[i-1].Start.AddHours(3),"effective starts remain three hours apart");});
   check("meal gap: completed prep never prevents postponing an unrecorded future meal",()=>{var s=New();var d=s.Days[0];d.GridBase.RemoveAll(x=>x.Category=="존2"||x.Category=="웨이트"||x.Category=="생활");var second=d.GridBase.Single(x=>x.MealId=="b6");second.Start=d.Wake.AddMinutes(180);d.GridBase.Single(x=>x.PrepFor=="b6").Start=second.Start.AddMinutes(-10);d.Records.Add(new CellBlock{Id="prep-fact",Start=d.Wake.AddMinutes(170),Count=1,Category="끼니 준비",Name="2끼니 준비",Score=1});var p=GridEngine.Build(s,d);Gaps(p);Assert(p.Blocks.Single(x=>x.MealId=="b6").Start==d.Wake.AddMinutes(210)&&d.Records[0].Start==d.Wake.AddMinutes(170),"future meal moved; actual prep preserved");});
  }
 }
}
